import re
from typing import List, Tuple

def perceive(observation_history: list[str]) -> str:
    """
    Parse the raw observation and produce a concise textual summary of
    decision-relevant features. The summary must change when the grid changes,
    enabling recovery of the action from two consecutive outputs.
    """
    if not observation_history:
        return "empty grid"  # fallback, should never happen

    raw = observation_history[-1]

    try:
        # Detect encoding type: look for JSON array first
        if raw.strip().startswith('[['):
            grid = parse_json_grid(raw)
        elif '<grid_' in raw:
            grid = parse_arc_grid(raw)
        else:
            # Try to find JSON anywhere in the text
            grid = parse_json_grid(raw)

        if grid is None or len(grid) == 0:
            return "empty grid"

        # Find the dominant (background) colour - most common cell value
        flat = [cell for row in grid for cell in row]
        if not flat:
            return "empty grid"

        # Count occurrences of each colour
        colour_counts = {}
        for cell in flat:
            colour_counts[cell] = colour_counts.get(cell, 0) + 1

        # Sort by frequency, get the most common as background
        sorted_colours = sorted(colour_counts.items(), key=lambda x: -x[1])
        if not sorted_colours:
            return "empty grid"

        background = sorted_colours[0][0]

        # Collect non-background cells
        non_bg_cells = []
        for r, row in enumerate(grid):
            for c, val in enumerate(row):
                if val != background:
                    non_bg_cells.append((r, c, val))

        if not non_bg_cells:
            return "empty grid"

        # Sort for deterministic output
        non_bg_cells.sort(key=lambda x: (x[0], x[1]))

        # Build concise summary
        parts = []
        for r, c, val in non_bg_cells:
            parts.append(f"({r},{c},{val})")

        # Group by colour for more concise representation
        summary = "; ".join(parts)

        # Add grid dimensions and background info for context
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        meta = f"grid={rows}x{cols} bg={background}"

        full_summary = f"{meta} | {summary}"

        # Ensure output is under 2000 chars
        if len(full_summary) > 1990:
            # Truncate by removing the middle part
            mid = len(full_summary) // 2
            half = 990
            full_summary = full_summary[:half] + "...[truncated]..." + full_summary[-half:]

        return full_summary

    except Exception as e:
        # Never raise, return best-effort summary
        return f"parse_error: {str(e)[:100]}"

def parse_json_grid(text: str) -> List[List]:
    """Parse a JSON 2D array of colour names from text."""
    try:
        # Find JSON array boundaries
        start = text.find('[[')
        if start == -1:
            return None

        # Find the matching closing brackets
        depth = 0
        end = -1
        for i in range(start, len(text)):
            if text[i] == '[':
                depth += 1
            elif text[i] == ']':
                depth -= 1
                if depth == 0:
                    end = i + 1
                    break

        if end == -1:
            return None

        json_str = text[start:end]
        grid = json.loads(json_str)

        # Convert to a uniform representation: all cell values are strings
        result = []
        for row in grid:
            result.append([str(cell) for cell in row])

        return result

    except (json.JSONDecodeError, ValueError, TypeError):
        return None

def parse_arc_grid(text: str) -> List[List]:
    """Parse ARC integer grid format."""
    try:
        # Find all grid blocks
        grids = []
        lines = text.split('\n')
        current_grid = None

        for line in lines:
            # Check for grid marker
            grid_match = re.match(r'<grid_(\d+)>', line.strip())
            if grid_match:
                if current_grid is not None:
                    grids.append(current_grid)
                current_grid = []
                continue

            # Try to parse a row
            if current_grid is not None:
                row_match = re.match(r'\[([^\]]+)\]', line.strip())
                if row_match:
                    try:
                        row = [int(x.strip()) for x in row_match.group(1).split(',')]
                        current_grid.append(row)
                    except ValueError:
                        continue

        if current_grid is not None and len(current_grid) > 0:
            grids.append(current_grid)

        # Use the first grid found
        if grids:
            grid = grids[0]
            # Convert integers to colour names for consistency
            colour_map = {
                0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
                5: "lightgray", 6: "magenta", 7: "orange", 8: "lightblue",
                9: "maroon", 10: "white", 11: "darkgray"
            }
            result = []
            for row in grid:
                result.append([colour_map.get(cell, f"x{cell}") for cell in row])
            return result

        return None

    except Exception:
        return None

